  `weapon_2` tinyint(2) DEFAULT 0,
  `weapon_3` tinyint(2) DEFAULT 0,
  `weapon_4` tinyint(2) DEFAULT 0,
  `weapon_5` tinyint(2) DEFAULT 0,
  `gangid` tinyint(2) DEFAULT -1,
  `ammo_1` int(10) NOT NULL DEFAULT 0,
