--
-- Runtime datatype and NULL normalization
--
-- Pawn cells and cache_get_value_name_int are signed 32-bit values.
UPDATE `users` SET `bank` = 2147483647 WHERE `bank` > 2147483647;
UPDATE `users` SET `bank` = -2147483648 WHERE `bank` < -2147483648;
UPDATE `users` SET `username` = CONCAT('legacy_', `uid`) WHERE `username` IS NULL OR `username` = '';
UPDATE `users` SET `password` = '' WHERE `password` IS NULL;
UPDATE `users` SET `ip` = '0.0.0.0' WHERE `ip` IS NULL OR `ip` = '';
UPDATE `users` SET `verify` = 0 WHERE `verify` IS NULL;

ALTER TABLE `users`
  MODIFY `username` varchar(24) NOT NULL,
  MODIFY `password` varchar(129) NOT NULL,
  MODIFY `ip` varchar(16) NOT NULL DEFAULT '0.0.0.0',
  MODIFY `bank` int(11) NOT NULL DEFAULT 500,
  MODIFY `verify` tinyint(1) NOT NULL DEFAULT 0;

UPDATE `vehicles` SET `milliage` = 0 WHERE `milliage` IS NULL;
UPDATE `vehicles` SET `hydro` = 0 WHERE `hydro` IS NULL;
UPDATE `vehicles` SET `vip` = 0 WHERE `vip` IS NULL;
UPDATE `vehicles` SET `carname` = 'None' WHERE `carname` IS NULL OR `carname` = '';

ALTER TABLE `vehicles`
  MODIFY `milliage` float NOT NULL DEFAULT 0,
  MODIFY `hydro` tinyint(4) NOT NULL DEFAULT 0,
  MODIFY `vip` tinyint(4) NOT NULL DEFAULT 0,
  MODIFY `carname` varchar(128) NOT NULL DEFAULT 'None';

